sha256_file() {
    sha256sum "$1" | awk '{print $1}'
}

write_b64() {
    local rel="$1"
    local payload="$2"
    local target="$REPO_DIR/$rel"
    local temp

    mkdir -p -- "$(dirname "$target")" || {
        fail "mkdir failed: $rel"
        return 1
    }

    temp="$(mktemp "${target}.tmp.XXXXXX")" || {
        fail "temporary file creation failed: $rel"
        return 1
    }

    if ! printf '%s' "$payload" | base64 -d >"$temp"; then
        rm -f -- "$temp"
        fail "base64 decode failed: $rel"
        return 1
    fi

    if ! mv -f -- "$temp" "$target"; then
        rm -f -- "$temp"
        fail "install failed: $rel"
        return 1
    fi

    pass "authored $rel"
}

cleanup() {
    local shell_rc=$?
    rm -rf -- "$python_cache_dir" 2>/dev/null || true

    if [ "$commit_created" -eq 0 ] && [ "$installation_started" -eq 1 ] && \
       { [ "$final_rc" -ne 0 ] || [ "$shell_rc" -ne 0 ]; }; then
        local rel
        for rel in "${TARGETS[@]}"; do
            rm -f -- "$REPO_DIR/$rel" 2>/dev/null || true
        done
        find "$REPO_DIR/rubrics/topic_packs/$TOPIC_ID" -depth -type d -empty -delete 2>/dev/null || true
        printf 'ROLLBACK_COMPLETED=true\n'
        print_context
    fi
}

trap cleanup EXIT

find_topic_commit() {
    local subject="$1"
    git log --format='%H%x09%s' |
        awk -F '\t' -v subject="$subject" '$2 == subject {print $1; exit}'
}

validate_prerequisite() {
    local subject="$1"
    shift
    local commit rel
    commit="$(find_topic_commit "$subject")"
    [ -n "$commit" ] || {
        fail "required Topic commit is not reachable: $subject"
        return 1
    }

    git merge-base --is-ancestor "$commit" HEAD >/dev/null 2>&1 || {
        fail "required Topic commit is not an ancestor of HEAD: $subject"
        return 1
    }

    for rel in "$@"; do
        git ls-files --error-unmatch -- "$rel" >/dev/null 2>&1 || {
            fail "required committed path is missing: $rel"
            return 1
        }
        git status --porcelain=v1 -- "$rel" | grep -q . && {
            fail "required committed path is not clean: $rel"
            return 1
        }
    done

    printf 'PREREQUISITE_COMMIT=%s|%s\n' "$commit" "$subject"
}

find_existing_complete_topic() {
    local commit rel
    commit="$(find_topic_commit "$COMMIT_SUBJECT")"
    [ -n "$commit" ] || return 1
    git merge-base --is-ancestor "$commit" HEAD >/dev/null 2>&1 || return 1

    for rel in "${COMMIT_PATHS[@]}"; do
        git ls-files --error-unmatch -- "$rel" >/dev/null 2>&1 || return 1
        git status --porcelain=v1 -- "$rel" | grep -q . && return 1
    done

    printf '%s' "$commit"
}

validate_source_schema() {
    python3 - "$REPO_DIR" "$TOPIC_ID" <<'PY_SCHEMA'
from __future__ import annotations

import json
import sys
from pathlib import Path

root = Path(sys.argv[1])
topic_id = sys.argv[2]
pack = root / "rubrics" / "topic_packs" / topic_id

def load(name: str) -> dict:
    return json.loads((pack / name).read_text(encoding="utf-8"))

fact = load("fact_anchor.json")
logic = load("logic_check.json")
model = load("model_answer.json")
importance = load("topic_importance.json")

for name, data in {
    "fact_anchor.json": fact,
    "logic_check.json": logic,
    "model_answer.json": model,
    "topic_importance.json": importance,
}.items():
    assert isinstance(data, dict), name
    assert data.get("topic_id") == topic_id, (name, data.get("topic_id"))

fact_required = {
    "schema_version", "topic_id", "title_ko", "question_type_hint",
    "anchors", "fatal_wrong_claims", "safe_expressions",
}
assert fact_required <= set(fact), sorted(fact_required - set(fact))
assert fact["schema_version"] == "fact_anchor.v1"
assert len(fact["anchors"]) == 30
assert len(fact["fatal_wrong_claims"]) == 16
assert len(fact["safe_expressions"]) >= 16

anchor_required = {
    "id", "anchor_id", "statement", "importance", "keywords", "core_terms",
    "accepted_explanations", "rejected_explanations", "grading_notes",
    "source_basis", "claim", "description",
}
for index, row in enumerate(fact["anchors"]):
    assert anchor_required <= set(row), (index, sorted(anchor_required - set(row)))
    assert row["id"] == row["anchor_id"]
    assert row["statement"] == row["claim"] == row["description"]
    assert row["keywords"] and row["core_terms"]
    assert row["accepted_explanations"]
    assert row["source_basis"]

fatal_required = {
    "id", "claim", "correction", "wrong_claim", "correct_rule", "severity",
    "affected_layers", "message", "description", "grading_notes",
}
for index, row in enumerate(fact["fatal_wrong_claims"]):
    assert fatal_required <= set(row), (index, sorted(fatal_required - set(row)))
    assert row["severity"] == "fatal"
    assert row["affected_layers"] == ["C"]

assert logic["schema_version"] == "topic_pack.logic_check.v1"
det = logic["deterministic_checks"]
assert det["enabled"] is False
for key in ("fatal_checks", "major_checks", "question_type_checks"):
    assert det[key] == []
profile = logic["llm_profile"]
assert profile["enabled"] is True
assert profile["candidate_extraction"]["rules"] == []
assert profile["score_policy"]["direct_score_application"] is False
assert profile["score_policy"]["direct_d_e_effect"] == "none"
assert profile["score_policy"]["affected_layers"] == ["C"]
assert len(profile["truth_schema"]) == 30
assert len(profile["fatal_conditions"]) == 16
assert len(profile["major_checks"]) == 12
assert len(profile["false_positive_cautions"]) >= 16

assert model["schema_version"] == "topic_pack.model_answer.v1"
assert model["question_type"] == "PRINCIPLE_INTERPRETATION"
assert len(model["expected_question_patterns"]) == 10
assert len(model["recommended_outline"]) == 8
assert len(model["routing_aliases"]) == 14

anchor_ids = {row["id"] for row in fact["anchors"]}
for row in model["expected_question_patterns"]:
    assert set(row["required_anchor_ids"]) <= anchor_ids
outline_union: set[str] = set()
for row in model["recommended_outline"]:
    refs = set(row["anchor_refs"])
    assert refs <= anchor_ids
    outline_union.update(refs)
assert outline_union == anchor_ids

assert importance["schema_version"] == "topic_pack.topic_importance.v1"
assert importance["difficulty"] == "THEORY_CORE"
assert importance["selection_importance"] == "CORE_MUST_PREPARE"
assert importance["question_type"] == "PRINCIPLE_INTERPRETATION"
assert len(importance["high_band_unlock_conditions"]) >= 10

fatal_ids = {row["id"] for row in fact["fatal_wrong_claims"]}
for required in {
    "accuracy_guarantees_safety",
    "train_test_same_data",
    "future_leakage_valid",
    "imbalance_accuracy_sufficient",
    "anomaly_score_certain_fault",
    "predictive_maintenance_prevents_all_failures",
    "rul_exact_date",
    "threshold_no_tradeoff",
    "retraining_always_improves",
    "explainability_proves_causality",
    "closed_loop_without_constraints",
}:
    assert required in fatal_ids, required

print("TOPIC_PACK_SCHEMA_VALIDATION=PASS")
print(f"ANCHORS={len(fact['anchors'])}")
print(f"FATALS={len(fact['fatal_wrong_claims'])}")
print(f"MAJORS={len(profile['major_checks'])}")
print(f"ALIASES={len(model['routing_aliases'])}")

PY_SCHEMA
}

validate_lane_ownership() {
    local base_ref merge_base rel
    if git rev-parse --verify --quiet "${REMOTE}/main" >/dev/null; then
        base_ref="${REMOTE}/main"
    elif git rev-parse --verify --quiet main >/dev/null; then
        base_ref="main"
    else
        fail "origin/main and local main are unavailable for Lane ownership audit"
        return 1
    fi

    merge_base="$(git merge-base HEAD "$base_ref")" || {
        fail "cannot compute merge-base against $base_ref"
        return 1
    }

    printf 'OWNERSHIP_BASE_REF=%s\n' "$base_ref"
    printf 'OWNERSHIP_MERGE_BASE=%s\n' "$merge_base"
    printf 'LANE_BRANCH_CHANGED_PATHS_BEGIN\n'

    while IFS= read -r rel; do
        [ -n "$rel" ] || continue
        printf '%s\n' "$rel"
        if ! is_lane_branch_path "$rel"; then
            fail "Lane branch path is outside Lane C ownership: $rel"
        fi
        case "$rel" in
            rubrics/generated/*)
                fail "Lane branch modifies forbidden generated path: $rel"
                ;;
            *.py)
                case "$rel" in
                    scripts/test_sis_sil_safety_software_topic.py|\
                    scripts/test_historian_mes_it_ot_data_integration_topic.py|\
                    "$TEST_REL")
                        ;;
                    *)
                        fail "Lane branch modifies production or non-focused Python: $rel"
                        ;;
                esac
                ;;
        esac
    done < <(git diff --name-only "$merge_base"..HEAD)

    printf 'LANE_BRANCH_CHANGED_PATHS_END\n'

    if git diff --name-only "$merge_base"..HEAD -- rubrics/generated/ | grep -q .; then
        fail "rubrics/generated/** changed on Lane C branch"
    else
        pass "rubrics/generated/** unchanged on Lane C branch"
    fi

    [ "$failure_count" -eq 0 ]
}

text_quality_validation() {
    python3 - "$REPO_DIR" "${TARGETS[@]}" <<'PY_TEXT'
from pathlib import Path
import sys

root = Path(sys.argv[1])
for rel in sys.argv[2:]:
    path = root / rel
    raw = path.read_bytes()
    raw.decode("utf-8")
    if not raw.endswith(b"\n"):
        raise SystemExit(f"missing final newline: {rel}")
    for number, line in enumerate(raw.decode("utf-8").splitlines(), start=1):
        if line.endswith((" ", "\t")):
            raise SystemExit(f"trailing whitespace: {rel}:{number}")
print("TEXT_QUALITY_VALIDATION=PASS")
PY_TEXT
}

main() {
    section "0. normalize invocation and verify immutable Lane C contract"

    local invocation_abs self_abs repo_abs current_branch
    invocation_abs="$(pwd -P 2>/dev/null || pwd)"
    self_abs="$(cd "$(dirname "$0")" && pwd -P)/$(basename "$0")"

    printf '%s\n' \
        "INVOCATION_ABSOLUTE_PATH=${invocation_abs}" \
        "SCRIPT_ABSOLUTE_PATH=${self_abs}" \
        "EXPECTED_SCRIPT_DIR=${EXPECTED_SCRIPT_DIR}" \
        "REPO_DIR=${REPO_DIR}" \
        "EXPECTED_BRANCH=${LANE_BRANCH}" \
        "REMOTE=${REMOTE}" \
        "MAIN_WORKTREE_PROHIBITED=/home/now0930/hermes/workspace/prof_eng_answer" \
        "LANE_A_WORKTREE_PROHIBITED=/home/now0930/hermes/workspace/prof_eng_answer_sw_lane_a" \
        "LANE_B_WORKTREE_PROHIBITED=/home/now0930/hermes/workspace/prof_eng_answer_sw_lane_b" \
        "GENERATED_REBUILD=false" \
        "VALIDATE_ALL=false" \
        "RELEASE_VALIDATION=false" \
        "EXTERNAL_LLM_VALIDATION=false" \
        "PUSH=false"

    if [ "$(dirname "$self_abs")" != "$EXPECTED_SCRIPT_DIR" ]; then
        fail "script is not placed in the Lane C gemini_script directory"
        return 1
    fi
    pass "script is placed in the Lane C gemini_script directory"

    if [ "$(basename "$self_abs")" != "$SELF_NAME" ]; then
        fail "script filename does not match the Lane C SW-12 contract"
        return 1
    fi
    pass "script filename matches the Lane C SW-12 contract"

    cd "$REPO_DIR" || {
        fail "cannot enter Lane C repository"
        return 1
    }

    repo_abs="$(pwd -P)"
    printf 'NORMALIZED_CURRENT_ABSOLUTE_PATH=%s\n' "$repo_abs"
    [ "$repo_abs" = "$REPO_DIR" ] || {
        fail "current absolute path does not match Lane C REPO_DIR"
        return 1
    }
    pass "current absolute path exactly matches Lane C REPO_DIR before mutation"

    case "$repo_abs" in
        "/home/now0930/hermes/workspace/prof_eng_answer"|\
        "/home/now0930/hermes/workspace/prof_eng_answer_sw_lane_a"|\
        "/home/now0930/hermes/workspace/prof_eng_answer_sw_lane_b")
            fail "main or another Lane worktree is prohibited"
            return 1
            ;;
        *)
            pass "main and Lane A/B worktrees are excluded"
            ;;
    esac

    git rev-parse --is-inside-work-tree >/dev/null 2>&1 || {
        fail "not a normal Git worktree"
        return 1
    }
    pass "normal Git worktree detected"

    [ "$(git rev-parse --show-toplevel)" = "$REPO_DIR" ] || {
        fail "Git top-level does not match Lane C REPO_DIR"
        return 1
    }
    printf 'GIT_TOPLEVEL=%s\n' "$(git rev-parse --show-toplevel)"
    pass "Git top-level exactly matches Lane C REPO_DIR"

    current_branch="$(git branch --show-current)"
    printf 'CURRENT_BRANCH=%s\n' "$current_branch"
    [ "$current_branch" = "$LANE_BRANCH" ] || {
        fail "current branch does not match Lane C branch"
        return 1
    }
    pass "current branch exactly matches Lane C branch"

    git remote get-url "$REMOTE" >/dev/null 2>&1 || {
        fail "remote origin is missing"
        return 1
    }
    printf 'REMOTE_URL=%s\n' "$(git remote get-url "$REMOTE")"
    pass "remote origin exists"

    section "1. verify SW-05 and SW-11 prerequisites and detect existing SW-12"
    set_stage "SW12_PREREQUISITE_VALIDATION" "SW12_SOURCE_AUTHORING"

    validate_prerequisite \
        "feat(topic-pack): add SW-05 SIS safety software topic" \
        "${SW05_REQUIRED_PATHS[@]}" || return 1

    validate_prerequisite \
        "feat(topic-pack): add SW-11 industrial data integration topic" \
        "${SW11_REQUIRED_PATHS[@]}" || return 1

    local existing_commit
    existing_commit="$(find_existing_complete_topic || true)"
    if [ -n "$existing_commit" ]; then
        if [ -f "$PACKAGE_REL" ] && ! git ls-files --error-unmatch -- "$PACKAGE_REL" >/dev/null 2>&1; then
            mv -- "$PACKAGE_REL" "/tmp/20260806_sw12_authoring_package.md" || {
                fail "cannot move reference-only package outside worktree"
                return 1
            }
        fi
        CURRENT_TOPIC="SW-13 physical_ai_robot_sensor_fusion_digital_twin_autonomous_manufacturing_safety_control"
        CURRENT_STAGE="SW12_ALREADY_COMMITTED"
        NEXT_STAGE="SW13_AUTHORING"
        LANE_PROGRESS="3/4"
        section "2. existing SW-12 completion report"
        printf '%s\n' \
            "LANE=${LANE}" \
            "SW_NUMBER=SW-12" \
            "TOPIC_ID=${TOPIC_ID}" \
            "COMMIT_HASH=${existing_commit}" \
            "COMMIT_SUBJECT=${COMMIT_SUBJECT}" \
            "VALIDATION_RESULT=EXISTING_TOPIC_COMMIT_AND_CLEAN_TARGETS_CONFIRMED" \
            "NEXT_TOPIC=${CURRENT_TOPIC}" \
            "LANE_PROGRESS=${LANE_PROGRESS}" \
            "PUSH_PERFORMED=false"
        return 0
    fi

    section "2. verify clean pre-mutation ownership baseline"
    set_stage "SW12_AUTHORING_PREFLIGHT" "SW12_SOURCE_AUTHORING"

    if git diff --cached --quiet; then
        pass "staging area is empty"
    else
        fail "staging area is not empty"
        return 1
    fi

    printf 'PREEXISTING_STATUS_BEGIN\n'
    git status --porcelain=v1 -uall
    printf 'PREEXISTING_STATUS_END\n'

    while IFS= read -r status_line; do
        [ -n "$status_line" ] || continue
        case "$status_line" in
            "?? $SELF_REL"|\
            "?? $PACKAGE_REL")
                ;;
            *)
                fail "pre-existing worktree change is outside the SW-12 script/package paths: $status_line"
                ;;
        esac
    done < <(git status --porcelain=v1 -uall)

    [ "$failure_count" -eq 0 ] || return 1

    if [ -f "$PACKAGE_REL" ]; then
        local package_target="/tmp/20260806_sw12_authoring_package.md"
        if [ -e "$package_target" ]; then
            package_target="/tmp/20260806_sw12_authoring_package.$(date +%Y%m%d%H%M%S).md"
        fi
        mv -- "$PACKAGE_REL" "$package_target" || {
            fail "cannot move reference-only SW-12 package outside worktree"
            return 1
        }
        printf 'MOVED_PACKAGE_TO=%s\n' "$package_target"
        pass "reference-only SW-12 package moved outside worktree"
    fi

    [ "$(git status --porcelain=v1 -uall)" = "?? $SELF_REL" ] || {
        fail "worktree does not contain exactly the SW-12 script before authoring"
        git status --short --branch
        return 1
    }
    pass "only the SW-12 authoring script is untracked before mutation"

    if git status --porcelain=v1 -- rubrics/generated/ | grep -q .; then
        fail "rubrics/generated/** has a pre-existing worktree change"
        return 1
    fi
    pass "rubrics/generated/** has no worktree change"

    for rel in "${TARGETS[@]}"; do
        if [ -e "$rel" ]; then
            fail "SW-12 target already exists without a complete committed Topic: $rel"
        fi
    done
    [ "$failure_count" -eq 0 ] || return 1

    set_stage "SW12_SOURCE_AUTHORING" "SW12_JSON_AND_SCHEMA_VALIDATION"
    section "3. author the complete SW-12 source Topic Pack"
    installation_started=1
    write_b64 "docs/topic_sheets/industrial_ai_machine_learning_anomaly_predictive_maintenance_model_lifecycle.md" ""
    write_b64 "rubrics/topic_packs/industrial_ai_machine_learning_anomaly_predictive_maintenance_model_lifecycle/README.md" ""
    write_b64 "rubrics/topic_packs/industrial_ai_machine_learning_anomaly_predictive_maintenance_model_lifecycle/fact_anchor.json" ""
    write_b64 "rubrics/topic_packs/industrial_ai_machine_learning_anomaly_predictive_maintenance_model_lifecycle/logic_check.json" ""
    write_b64 "rubrics/topic_packs/industrial_ai_machine_learning_anomaly_predictive_maintenance_model_lifecycle/model_answer.json" ""
    write_b64 "rubrics/topic_packs/industrial_ai_machine_learning_anomaly_predictive_maintenance_model_lifecycle/topic_importance.json" ""
    write_b64 "scripts/test_industrial_ai_ml_model_lifecycle_topic.py" ""
    chmod 755 "$TEST_REL" || {
        fail "failed to chmod focused test"
        return 1
    }

    set_stage "SW12_JSON_AND_SCHEMA_VALIDATION" "SW12_FOCUSED_VALIDATION"
    section "4. validate JSON syntax and Topic Pack schema"

    local rel actual_hash
    for rel in "${JSON_PATHS[@]}"; do
        if python3 -m json.tool "$rel" >/dev/null; then
            pass "JSON syntax: $rel"
        else
            fail "JSON syntax: $rel"
        fi
    done

    if validate_source_schema; then
        pass "focused Topic Pack schema contract"
    else
        fail "focused Topic Pack schema contract"
    fi

    for rel in "${TARGETS[@]}"; do
        actual_hash="$(sha256_file "$rel")"
        printf 'SOURCE_SHA256=%s|%s\n' "$rel" "$actual_hash"
        if [ "$actual_hash" = "${EXPECTED_SHA256[$rel]}" ]; then
            pass "reviewed source payload hash: $rel"
        else
            fail "source payload hash mismatch: $rel"
        fi
    done
    [ "$failure_count" -eq 0 ] || return 1

    set_stage "SW12_FOCUSED_VALIDATION" "SW12_OWNERSHIP_VALIDATION"
    section "5. run focused validation without external LLM"

    if python3 -m py_compile "$TEST_REL"; then
        pass "py_compile changed focused-test Python only"
    else
        fail "focused-test py_compile"
    fi

    if python3 "$TEST_REL"; then
        pass "SW-12 focused regression"
    else
        fail "SW-12 focused regression"
    fi

    printf '%s\n' \
        "SEMANTIC_VALIDATION=PASS_BY_CHATGPT_AUTHORING_REVIEW" \
        "SEMANTIC_SCOPE=AI_ML_TASKS,SPLIT_LEAKAGE_IMBALANCE,METRICS_THRESHOLD,RUL_DRIFT_RETRAINING,EXPLAINABILITY_MLOPS" \
        "EXTERNAL_LLM_VALIDATION_RUN=false"
    pass "ChatGPT-authored semantic guard contract is embedded in Anchor, Fatal, Major and false-positive records"
    [ "$failure_count" -eq 0 ] || return 1

    set_stage "SW12_OWNERSHIP_VALIDATION" "SW12_LOCAL_COMMIT"
    section "6. validate diff, text quality and Lane C ownership"

    if git diff --check -- "${TARGETS[@]}"; then
        pass "git diff --check for SW-12 source files"
    else
        fail "git diff --check for SW-12 source files"
    fi

    if text_quality_validation; then
        pass "UTF-8 text, trailing-whitespace and final-newline checks"
    else
        fail "text quality validation"
    fi

    printf 'AUTHORING_STATUS_BEGIN\n'
    git status --porcelain=v1 -uall
    printf 'AUTHORING_STATUS_END\n'

    while IFS= read -r status_line; do
        [ -n "$status_line" ] || continue
        local path="${status_line:3}"
        if ! is_commit_path "$path"; then
            fail "authoring worktree path is outside the exact SW-12 commit contract: $status_line"
        fi
    done < <(git status --porcelain=v1 -uall)

    if git status --porcelain=v1 -- rubrics/generated/ | grep -q .; then
        fail "rubrics/generated/** changed during SW-12 authoring"
    else
        pass "rubrics/generated/** unchanged during SW-12 authoring"
    fi
    [ "$failure_count" -eq 0 ] || return 1

    set_stage "SW12_LOCAL_COMMIT" "SW12_POST_COMMIT_VALIDATION"
    section "7. create the SW-12 local Topic commit"

    git add -- "${COMMIT_PATHS[@]}" || {
        fail "git add failed for SW-12 commit paths"
        return 1
    }

    local -a staged_paths expected_paths committed_paths
    mapfile -t staged_paths < <(git diff --cached --name-only | LC_ALL=C sort)
    mapfile -t expected_paths < <(printf '%s\n' "${COMMIT_PATHS[@]}" | LC_ALL=C sort)

    printf 'STAGED_PATHS_BEGIN\n'
    printf '%s\n' "${staged_paths[@]}"
    printf 'STAGED_PATHS_END\n'

    if [ "${#staged_paths[@]}" -ne "${#expected_paths[@]}" ]; then
        fail "staged path count differs from exact SW-12 contract"
    else
        local index
        for index in "${!expected_paths[@]}"; do
            if [ "${staged_paths[$index]}" != "${expected_paths[$index]}" ]; then
                fail "staged path mismatch: expected=${expected_paths[$index]} actual=${staged_paths[$index]}"
            fi
        done
    fi

    if git diff --cached --check; then
        pass "staged diff check"
    else
        fail "staged diff check"
    fi
    [ "$failure_count" -eq 0 ] || return 1

    if git commit -m "$COMMIT_SUBJECT"; then
        commit_created=1
        installation_started=0
        pass "SW-12 local Topic commit created"
    else
        fail "SW-12 local Topic commit failed"
        return 1
    fi

    local commit_hash commit_subject
    commit_hash="$(git rev-parse HEAD)"
    commit_subject="$(git log -1 --pretty=%s)"

    [ "$commit_subject" = "$COMMIT_SUBJECT" ] || {
        fail "commit subject mismatch"
        return 1
    }
    pass "commit subject matches SW-12 contract"

    mapfile -t committed_paths < <(git diff-tree --no-commit-id --name-only -r HEAD | LC_ALL=C sort)
    printf 'COMMITTED_FILES_BEGIN\n'
    printf '%s\n' "${committed_paths[@]}"
    printf 'COMMITTED_FILES_END\n'

    if [ "${#committed_paths[@]}" -ne "${#expected_paths[@]}" ]; then
        fail "committed path count differs from exact SW-12 contract"
    else
        local index
        for index in "${!expected_paths[@]}"; do
            if [ "${committed_paths[$index]}" != "${expected_paths[$index]}" ]; then
                fail "committed path mismatch: expected=${expected_paths[$index]} actual=${committed_paths[$index]}"
            fi
        done
    fi
    [ "$failure_count" -eq 0 ] || return 1

    set_stage "SW12_POST_COMMIT_VALIDATION" "SW13_AUTHORING"
    section "8. validate the committed Lane C state"

    if git status --porcelain=v1 | grep -q .; then
        printf 'POST_COMMIT_STATUS_BEGIN\n'
        git status --short --branch
        printf 'POST_COMMIT_STATUS_END\n'
        fail "working tree is not clean after the SW-12 commit"
    else
        pass "working tree is clean after the SW-12 commit"
    fi

    validate_lane_ownership || return 1

    if git log -1 --format='%H%x09%s' | grep -Fq "$commit_hash"$'\t'"$COMMIT_SUBJECT"; then
        pass "HEAD is the expected SW-12 Topic commit"
    else
        fail "HEAD does not match the expected SW-12 Topic commit"
    fi
    [ "$failure_count" -eq 0 ] || return 1

    CURRENT_TOPIC="SW-13 physical_ai_robot_sensor_fusion_digital_twin_autonomous_manufacturing_safety_control"
    CURRENT_STAGE="SW12_COMMITTED_AND_VALIDATED"
    NEXT_STAGE="SW13_AUTHORING"
    LANE_PROGRESS="3/4"

    section "9. SW-12 completion report"

    printf '%s\n' \
        "LANE=${LANE}" \
        "SW_NUMBER=SW-12" \
        "TOPIC_ID=${TOPIC_ID}" \
        "COMMIT_HASH=${commit_hash}" \
        "COMMIT_SUBJECT=${commit_subject}" \
        "VALIDATION_RESULT=PASS" \
        "JSON_SYNTAX=PASS" \
        "TOPIC_PACK_SCHEMA=PASS" \
        "FOCUSED_TEST=PASS" \
        "PY_COMPILE=PASS_FOCUSED_TEST_ONLY" \
        "GIT_DIFF_CHECK=PASS" \
        "LANE_C_OWNERSHIP=PASS" \
        "WORKING_TREE_CLEAN=true" \
        "GENERATED_BANK_CHANGED=false" \
        "EXTERNAL_LLM_VALIDATION_RUN=false" \
        "PUSH_PERFORMED=false" \
        "REMOTE_PUSH_DEFERRED_UNTIL_LANE_PROGRESS_4_OF_4=true" \
        "NEXT_TOPIC=${CURRENT_TOPIC}" \
        "LANE_PROGRESS=${LANE_PROGRESS}"
    print_context

    return 0
}

main || final_rc=$?

(return "$final_rc" 2>/dev/null) || [ "$final_rc" -eq 0 ]
